INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (21, 11, 'Chính Sách & Điều Kiện Sử Dụng: Saigon Prince - Buffet Cua Biển, Hải Sản Không Giới Hạn', $BODY$Điều kiện sử dụng

