INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (77, 39, 'Chính Sách & Điều Kiện Sử Dụng: Quốc Huy Hair Salon - Trọn Gói Làm Tóc + Phục Hồi - SP Ý', $BODY$Điều kiện sử dụng

