INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (91, 46, 'Chính Sách & Điều Kiện Sử Dụng: VTM Úc Châu - Gội Đầu Dưỡng Sinh + Massage Đầu, Cổ, Vai, Gáy', $BODY$Điều kiện sử dụng

