INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (93, 47, 'Chính Sách & Điều Kiện Sử Dụng: VTM Úc Châu - Massage Đả Thông Kinh Lạc Trị Liệu Đau Cổ Vai Gáy', $BODY$Điều kiện sử dụng

