INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (99, 50, 'Chính Sách & Điều Kiện Sử Dụng: Skin Lab By Hung Nguyen - Giảm Béo Siêu Tốc CN Sóng Quang Đông', $BODY$Điều kiện sử dụng

