INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (125, 63, 'Chính Sách & Điều Kiện Sử Dụng: Skin Lab By Hung Nguyen - Điều Trị Nám Công Nghệ Laser YAG 3 Korea', $BODY$Điều kiện sử dụng

