INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (131, 66, 'Chính Sách & Điều Kiện Sử Dụng: Sun Nails - Trọn Gói Chăm Sóc Móng Tay/ Đôi Bàn Chân', $BODY$Điều kiện sử dụng

