INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (133, 67, 'Chính Sách & Điều Kiện Sử Dụng: Ivora Skinlab - Cryo CN Hàn Quốc - Sạch Da, Trắng Mịn, Căng Bóng Da', $BODY$Điều kiện sử dụng

