INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (139, 70, 'Chính Sách & Điều Kiện Sử Dụng: Lotus Spa - Massage Trị Liệu Cổ Vai Gáy + Gội Đầu + Chăm Sóc Da', $BODY$Điều kiện sử dụng

