INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (145, 73, 'Chính Sách & Điều Kiện Sử Dụng: Paradise Spa - Massage Body/ Vai Gáy/ Đả Thông Kinh Lạc/ Gội Đầu', $BODY$Điều kiện sử dụng

