INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (151, 76, 'Chính Sách & Điều Kiện Sử Dụng: Ruka Spa - Trọn Gói Massage Body + Gội Đầu Dưỡng Sinh 135’', $BODY$Điều kiện sử dụng

