INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (161, 81, 'Chính Sách & Điều Kiện Sử Dụng: Ty House Spa - Massage Body/ Chạy Vitamin C/ Trị Mụn/ Giảm Béo', $BODY$Điều kiện sử dụng

