INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (164, 82, 'Trải Nghiệm Dịch Vụ & Điểm Nổi Bật: Phương Uyên Spa - Massage Body/ Chăm Sóc Da/ Gội Đầu Dưỡng Sinh', $BODY$Thông tin chi tiết

