INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (175, 88, 'Chính Sách & Điều Kiện Sử Dụng: Nha Khoa Sao Việt - Cạo Vôi, Đánh Bóng/ Trám Răng Chất Lượng Cao', $BODY$Điều kiện sử dụng

