INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (199, 100, 'Chính Sách & Điều Kiện Sử Dụng: Ivora Skinlab - Gội Đầu Thảo Dược + Ủ Tóc + Massage Cổ Vai Gáy', $BODY$Điều kiện sử dụng

