INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (223, 112, 'Chính Sách & Điều Kiện Sử Dụng: Marina Bay Resort Vũng Tàu 5* - P. Deluxe 2N1Đ + Ăn Sáng - 2 Khách', $BODY$Điều kiện sử dụng

