INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (309, 155, 'Chính Sách & Điều Kiện Sử Dụng: Tour 1/2 Ngày Tham Quan Địa Đạo Củ Chi', $BODY$Điều kiện sử dụng

