INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (331, 166, 'Chính Sách & Điều Kiện Sử Dụng: Tour VMB 5N4Đ - Hà Nội - Hà Giang - Lũng Cú - Sapa - Fansipan - DLHD02', $BODY$Điều kiện sử dụng

